import sys
import os
import json
import re
from datetime import datetime, timedelta

def parse_sql(content):
    """
    A simple parser for the provided SQL format.
    Extracts table names and their rows as lists of dictionaries.
    """
    tables = {}
    # Find CREATE TABLE statements to get column names
    create_matches = re.finditer(r"CREATE TABLE (\w+) \((.*?)\);", content, re.DOTALL)
    for match in create_matches:
        table_name = match.group(1)
        cols_text = match.group(2)
        cols = []
        for line in cols_text.split(','):
            line = line.strip()
            if not line: continue
            parts = line.split()
            if parts:
                cols.append(parts[0])
        tables[table_name] = {"cols": cols, "rows": []}

    # Find INSERT INTO statements
    insert_matches = re.finditer(r"INSERT INTO (\w+) \((.*?)\) VALUES (.*?);", content, re.DOTALL)
    for match in insert_matches:
        table_name = match.group(1)
        if table_name not in tables: continue

        cols_text = match.group(2)
        cols = [c.strip() for c in cols_text.split(',')]

        values_block = match.group(3).strip()
        # Values can be multiple tuples: (1, 'A', 10), (2, 'B', 20)
        # We split by '), (' but need to be careful with commas inside quotes
        # Since the data is simple, we use a regex to find tuples
        tuples = re.findall(r"\((.*?)\)(?:,|$)", values_block, re.DOTALL)

        for tup_str in tuples:
            # Split by comma, but ignore commas inside single quotes
            parts = []
            current = []
            in_quotes = False
            for char in tup_str:
                if char == "'" :
                    in_quotes = not in_quotes
                    current.append(char)
                elif char == ',' and not in_quotes:
                    parts.append("".join(current).strip())
                    current = []
                else:
                    current.append(char)
            parts.append("".join(current).strip())

            row = {}
            for i, val in enumerate(parts):
                if i < len(cols):
                    col_name = cols[i]
                    if val.upper() == 'NULL':
                        row[col_name] = None
                    elif val.startswith("'") and val.endswith("'"):
                        row[col_name] = val[1:-1]
                    else:
                        try:
                            if '.' in val:
                                row[col_name] = float(val)
                            else:
                                row[col_name] = int(val)
                        except ValueError:
                            row[col_name] = val
            tables[table_name]["rows"].append(row)

    return tables

def epd_to_date(epd):
    if epd is None: return None
    return datetime(1970, 1, 1) + timedelta(days=int(epd))

def format_date(dt):
    if dt is None: return None
    return dt.strftime('%Y-%m-%d')

