def get_value(segments, segment_id, qualifier=None, key_field_idx=None, key_val=None):
    """
    Searches segments for a specific value. 
    If key_field_idx and key_val are provided, it filters by a key (like LIN**BP*P-XXXXX).
    """
    current_lx_data = []
    for seg in segments:
        if seg[0] == 'LX':
            if current_lx_data:
                yield current_lx_data
            current_lx_data = [seg]
        else:
            current_lx_data.append(seg)
    if current_lx_data:
        yield current_lx_data

def extract_data(directory):
