import sys
import os
import json
import re
from datetime import datetime

def parse_date(date_str):
    if not date_str:
        return None
    # Clean up common formats
    date_str = date_str.strip().lower()
    # Remove ordinal suffixes (st, nd, rd, th) from days
    date_str = re.sub(r'(\d+)(st|nd|rd|th)', r'\1', date_str)

    formats = [
        "%b %d, %Y",    # March 1st, 2026 -> March 1, 2026
        "%d %b %Y",     # 11th Jan 2026 -> 11 Jan 2026
        "%B %d, %Y",    # March 1, 2026
        "%d %B %Y",     # 11 January 2026
        "%b %d %Y",     # Mar 1 2026
        "%d %b %Y",     # 1 Mar 2026
        "%Y-%m-%d"
    ]

    # Handle "June 11th, 2026" style
    for fmt in formats:
        try:
            return datetime.strptime(date_str, fmt)
        except ValueError:
            continue
    return None

def parse_amount(amount_str):
    if not amount_str:
        return None
    # Extract number from string like "481 kilonewtons" or "243 kN"
    match = re.search(r'(\d+(\.\d+)?)', amount_str)
    if match:
        return float(match.group(1))
    return None

def load_files(directory):
    files = {}
    for filename in os.listdir(directory):
        path = os.path.join(directory, filename)
        if os.path.isfile(path):
            with open(path, 'r') as f:
                files[filename] = f.read()
    return files

def extract_data(files):
    data = {
        'calibration_log': [],
        'lab_certificates': [],
        'parts': [],
        'spec_sheets': [],
        'test_reports': []
    }

    mapping = {
        'calibration_log.txt': 'calibration_log',
        'lab_certificates.txt': 'lab_certificates',
        'parts.txt': 'parts',
        'spec_sheets.txt': 'spec_sheets',
        'test_reports.txt': 'test_reports'
    }

    for fname, content in files.items():
        if fname not in mapping:
            continue

        key = mapping[fname]
        # Split by message separator
        messages = content.split('========================================================================')
        for msg in messages:
            if 'Subject:' not in msg:
                continue

            # Extract Part ID from Subject
            part_match = re.search(r'P-\d+', msg)
            if not part_match:
                continue
            part_id = part_match.group(0)

            entry = {'part_id': part_id, 'raw': msg}

            if key == 'calibration_log':
                # Look for calibration date
                # "last calibrated on June 16th, 2026" or "sticker says March 1st, 2026"
                cal_match = re.search(r'(?:calibrated on|sticker says) ([A-Za-z]+ \d+(?:st|nd|rd|th)?,? \d{4}|\d+(?:st|nd|rd|th)? [A-Za-z]+,? \d{4})', msg)
                if cal_match:
                    entry['calibration_date'] = cal_match.group(1)

            elif key == 'lab_certificates':
                # "lab test happened on 3rd Jun 2027"
                test_match = re.search(r'lab test happened on ([A-Za-z]+ \d+(?:st|nd|rd|th)?,? \d{4}|\d+(?:st|nd|rd|th)? [A-Za-z]+,? \d{4})', msg)
                if test_match:
                    entry['test_date'] = test_match.group(1)
                # "certifies failure at 156 kilonewtons" or "failed at 446 kilonewtons" or "failed at 176 kN"
                fail_match = re.search(r'(?:certifies failure at|failed at) (\d+(?:\.\d+)?)\s*(?:kilonewtons|kN)', msg)
                if fail_match:
                    entry['measured_load'] = fail_match.group(1)
                # "ran it on 7th Feb 2027"
                run_match = re.search(r'ran it on ([A-Za-z]+ \d+(?:st|nd|rd|th)?,? \d{4}|\d+(?:st|nd|rd|th)? [A-Za-z]+,? \d{4})', msg)
                if run_match:
                    entry['test_date'] = run_match.group(1)

            elif key == 'parts':
                # "Design objective is 166 kilonewtons at failure"
                obj_match = re.search(r'Design objective is (\d+(?:\.\d+)?)\s*(?:kilonewtons|kN)', msg)
                if obj_match:
                    entry['specified_minimum'] = obj_match.group(1)
                # "break test is booked for 20th Apr 2027"
                book_match = re.search(r'break test is booked for ([A-Za-z]+ \d+(?:st|nd|rd|th)?,? \d{4}|\d+(?:st|nd|rd|th)? [A-Za-z]+,? \d{4})', msg)
                if book_match:
                    entry['break_test_date'] = book_match.group(1)

            elif key == 'spec_sheets':
                # "drawing calls for at least 130 kilonewtons at failure"
                spec_match = re.search(r'drawing calls for at least (\d+(?:\.\d+)?)\s*(?:kilonewtons|kN)', msg)
