import sys
import os
import json
import re
from datetime import datetime

def parse_date(date_str):
    if not date_str: return None
    date_str = date_str.strip().lower()
    date_str = re.sub(r'(\d+)(st|nd|rd|th)', r'\1', date_str)
    formats = ["%b %d, %Y", "%d %b %Y", "%B %d, %Y", "%d %B %Y", "%b %d %Y", "%d %b %Y", "%Y-%m-%d"]
    for fmt in formats:
        try: return datetime.strptime(date_str, fmt)
        except ValueError: continue
    return None

def parse_amount(amount_str):
    if not amount_str: return None
    match = re.search(r'(\d+(\.\d+)?)', amount_str)
    return float(match.group(1)) if match else None

def load_files(directory):
    files = {}
    for filename in os.listdir(directory):
        path = os.path.join(directory, filename)
        if os.path.isfile(path):
            with open(path, 'r') as f: files[filename] = f.read()
    return files

def extract_data(files):
    data = {'calibration_log': [], 'lab_certificates': [], 'parts': [], 'spec_sheets': [], 'test_reports': []}
    mapping = {'calibration_log.txt': 'calibration_log', 'lab_certificates.txt': 'lab_certificates', 'parts.txt': 'parts', 'spec_sheets.txt': 'spec_sheets', 'test_reports.txt': 'test_reports'}
    for fname, content in files.items():
        if fname not in mapping: continue
        key = mapping[fname]
        messages = content.split('========================================================================')
        for msg in messages:
            if 'Subject:' not in msg: continue
            part_match = re.search(r'P-\d+', msg)
            if not part_match: continue
            pid = part_match.group(0)
            entry = {'part_id': pid}
            if key == 'calibration_log':
                m = re.search(r'(?:calibrated on|sticker says) ([A-Za-z]+ \d+(?:st|nd|rd|th)?,? \d{4}|\d+(?:st|nd|rd|th)? [A-Za-z]+,? \d{4})', msg)
                if m: entry['calibration_date'] = m.group(1)
            elif key == 'lab_certificates':
                m1 = re.search(r'lab test happened on ([A-Za-z]+ \d+(?:st|nd|rd|th)?,? \d{4}|\d+(?:st|nd|rd|th)? [A-Za-z]+,? \d{4})', msg)
                if m1: entry['test_date'] = m1.group(1)
                m2 = re.search(r'(?:certifies failure at|failed at) (\d+(?:\.\d+)?)\s*(?:kilonewtons|kN)', msg)
                if m2: entry['measured_load'] = m2.group(1)
                m3 = re.search(r'ran it on ([A-Za-z]+ \d+(?:st|nd|rd|th)?,? \d{4}|\d+(?:st|nd|rd|th)? [A-Za-z]+,? \d{4})', msg)
                if m3: entry['test_date'] = m3.group(1)
            elif key == 'parts':
                m1 = re.search(r'Design objective is (\d+(?:\.\d+)?)\s*(?:kilonewtons|kN)', msg)
                if m1: entry['specified_minimum'] = m1.group(1)
                m2 = re.search(r'break test is booked for ([A-Za-z]+ \d+(?:st|nd|rd|th)?,? \d{4}|\d+(?:st|nd|rd|th)? [A-Za-z]+,? \d{4})', msg)
                if m2: entry['break_test_date'] = m2.group(1)
            elif key == 'spec_sheets':
                m1 = re.search(r'(?:drawing calls for at least|Drawing minimum at failure is) (\d+(?:\.\d+)?)\s*(?:kilonewtons|kN)', msg)
                if m1: entry['specified_minimum'] = m1.group(1)
            elif key == 'test_reports':
                m1 = re.search(r'(?:break test ran on|broke it on the frame on) ([A-Za-z]+ \d+(?:st|nd|rd|th)?,? \d{4}|\d+(?:st|nd|rd|th)? [A-Za-z]+,? \d{4})', msg)
                if m1: entry['test_date'] = m1.group(1)
                m2 = re.search(r'(?:recorded failure at|let go at) (\d+(?:\.\d+)?)\s*(?:kilonewtons|kN)', msg)
                if m2: entry['measured_load'] = m2.group(1)
            data[key].append(entry)
    return data

def get_val_refined(pid, doc_configs, fallback_doc_key, data):
    for doc_key, field_name in doc_configs:
        found_vals, found_doc = [], None
        for entry in data[doc_key]:
