import csv
from datetime import datetime, timedelta

def parse_iso_week(week_str):
    """Parses YYYY-Www-D format to a datetime object."""
    if not week_str or week_str == '~':
        return None
    try:
        # Format: 2026-W06-7
        parts = week_str.split('-')
        year = int(parts[0])
        week = int(parts[1][1:])
        day = int(parts[2])
        # datetime.strptime %G %V %u handles ISO week dates
        return datetime.strptime(f"{year} {week} {day}", "%G %V %u")
    except (ValueError, IndexError):
        return None

def load_tsv(directory, filename):
    path = os.path.join(directory, filename)
    if not os.path.exists(path):
        return {}

    data = {}
    with open(path, 'r', encoding='utf-8') as f:
        reader = csv.reader(f, delimiter='\t')
        rows = list(reader)

    if not rows:
        return {}

    # Find header row (the one starting with 'attribute')
    header_idx = -1
    for i, row in enumerate(rows):
        if row and row[0] == 'attribute':
            header_idx = i
            break

    if header_idx == -1:
        return {}

    header = rows[header_idx]
    # The columns are rec.01, rec.02, etc.
    # We want to map attribute -> {rec_id: value}
    for i in range(len(header)):
        attr = header[i]
        if attr == 'attribute':
            continue

        # For every row after the header, if the first column matches 'attr'
        for r in range(header_idx + 1, len(rows)):
            row = rows[r]
            if len(row) > i and row[0] == attr:
                val = row[i]
                if attr not in data:
                    data[attr] = {}
                data[attr][header[i]] = val
    return data

