    pattern = re.compile(r"INSERT INTO (\w+) \((.*?)\) VALUES \((.*?)\);", re.DOTALL)
    matches = pattern.findall(content)

    data = []
    for table, cols_str, vals_str in matches:
        cols = [c.strip() for c in cols_str.split(',')]
        # Split values by comma, but respect potential strings (though not present in these specific files)
        # For these files, values are simple: 'string', number, or NULL
        vals_raw = []
