        # We use a regex to find either 'string' or numbers/NULL
        vals_raw = re.findall(r"'(.*?)'|(\d+\.?\d*)|(NULL)", vals_str)

        row = {}
        for i, col in enumerate(cols):
            # vals_raw[i] is a tuple (string_val, num_val, null_val)
            if vals_raw[i][0]: # string
                val = vals_raw[i][0]
            elif vals_raw[i][1]: # number
                val = vals_raw[i][1]
            elif vals_raw[i][2]: # NULL
