import sys
import os
import json
import re
from datetime import datetime

def parse_date(date_str):
    if not date_str:
        return None
    # Try various formats found in the text
    formats = [
        "%B %d %Y",    # March 2nd, 2026 -> March 2 2026
        "%d %b %Y",    # 27th Jun 2026 -> 27 Jun 2026
        "%d %B %Y",    # January 1st, 2026 -> January 1 2026
        "%B %d, %Y",   # April 13th, 2026 -> April 13, 2026
        "%d %B %Y",    # 4th Feb 2027 -> 4 Feb 2027
        "%Y-%m-%d",
        "%d %b %Y",
        "%B %d %Y"
    ]

    # Clean up ordinal suffixes (st, nd, rd, th)
    clean_str = re.sub(r'(\d+)(st|nd|rd|th)', r'\1', date_str)

    for fmt in formats:
        try:
            return datetime.strptime(clean_str, fmt)
        except ValueError:
            continue
    return None

def parse_amount(text):
    # Extract number from strings like "454 kilonewtons", "401 kN", "454"
    match = re.search(r'(\d+(?:\.\d+)?)', text)
    if match:
        return float(match.group(1))
    return None

def solve():
    if len(sys.argv) < 2:
        return

    dir_path = sys.argv[1]
    files = {}
    for filename in os.listdir(dir_path):
        with open(os.path.join(dir_path, filename), 'r') as f:
            files[filename] = f.read()

    # Data structures to hold extracted facts
    # calibration_log: {part_id: {calibration_date: (val, doc)}}
    cal_log = {}
    # lab_certificates: {part_id: {test_date: (val, doc), failure_load: (val, doc)}}
    lab_certs = {}
    # test_reports: {part_id: {test_date: (val, doc), failure_load: (val, doc)}}
    test_reps = {}
    # spec_sheets: {part_id: {min_failure_load: (val, doc)}}
    spec_sheets = {}

    # --- Parsing calibration_log ---
    messages = files.get('calibration_log.txt', '').split('========================================================================')
    for msg in messages:
        subject_match = re.search(r'Subject: .* - (P-\d+)', msg)
        if not subject_match: continue
        pid = subject_match.group(1)

        # Look for calibration date
        # Patterns: "last calibrated on March 2nd, 2026", "sticker says February 28th, 2026"
        date_match = re.search(r'(?:calibrated on|sticker says) ([A-Za-z]+ \d+(?:st|nd|rd|th)?,? \d{4}|\d+(?:st|nd|rd|th)? [A-Za-z]+ \d{4})', msg)
        if date_match:
            dt = parse_date(date_match.group(1))
            if dt:
                if pid not in cal_log: cal_log[pid] = {}
                cal_log[pid]['calibration_date'] = (dt.strftime('%Y-%m-%d'), 'calibration_log.txt')

    # --- Parsing lab_certificates ---
    messages = files.get('lab_certificates.txt', '').split('========================================================================')
    for msg in messages:
        subject_match = re.search(r'Subject: .* - (P-\d+)', msg)
        if not subject_match: continue
        pid = subject_match.group(1)

        # Test date
        date_match = re.search(r'(?:ran it on|happened on) ([A-Za-z]+ \d+(?:st|nd|rd|th)?,? \d{4}|\d+(?:st|nd|rd|th)? [A-Za-z]+ \d{4})', msg)
        if date_match:
            dt = parse_date(date_match.group(1))
            if dt:
                if pid not in lab_certs: lab_certs[pid] = {}
                lab_certs[pid]['test_date'] = (dt.strftime('%Y-%m-%d'), 'lab_certificates.txt')

        # Failure load
        load_match = re.search(r'failure at (\d+(?:\.\d+)?) ?(?:kilonewtons|kN)', msg)
        if load_match:
            if pid not in lab_certs: lab_certs[pid] = {}
            lab_certs[pid]['measured_load'] = (load_match.group(1), 'lab_certificates.txt')

    # --- Parsing test_reports ---
    messages = files.get('test_reports.txt', '').split('========================================================================')
    for msg in messages:
        subject_match = re.search(r'Subject: .* - (P-\d+)', msg)
        if not subject_match: continue
        pid = subject_match.group(1)

        # Test date
        date_match = re.search(r'(?:ran on|broke it on the frame on) ([A-Za-z]+ \d+(?:st|nd|rd|th)?,? \d{4}|\d+(?:st|nd|rd|th)? [A-Za-z]+ \d{4})', msg)
        if date_match:
            dt = parse_date(date_match.group(1))
            if dt:
                if pid not in test_reps: test_reps[pid] = {}
                test_reps[pid]['test_date'] = (dt.strftime('%Y-%m-%d'), 'test_reports.txt')

        # Failure load
        load_match = re.search(r'(?:recorded failure at|let go at) (\d+(?:\.\d+)?) ?(?:kilonewtons|kN)', msg)
        if load_match:
            if pid not in test_reps: test_reps[pid] = {}
            test_reps[pid]['measured_load'] = (load_match.group(1), 'test_reports.txt')

    # --- Parsing spec_sheets ---
    messages = files.get('spec_sheets.txt', '').split('========================================================================')
    for msg in messages:
        subject_match = re.search(r'Subject: .* - (P-\d+)', msg)
        if not subject_match: continue
        pid = subject_match.group(1)

        load_match = re.search(r'(?:minimum at failure is|calls for at least) (\d+(?:\.\d+)?) ?(?:kilonewtons|kN)', msg)
        if load_match:
            if pid not in spec_sheets: spec_sheets[pid] = {}
            spec_sheets[pid]['specified_minimum'] = (load_match.group(1), 'spec_sheets.txt')

    # --- Final Processing ---
    results = {}
    pids = [f"P-{i}" for i in range(40901, 40917)]

    for pid in pids:
        # ea.calibration_current
        # calibration date
        cal_date_val = cal_log.get(pid, {}).get('calibration_date', "ABSENT")
        # test date
        test_date_val = "ABSENT"
        if pid in test_reps and 'test_date' in test_reps[pid]:
            test_date_val = test_reps[pid]['test_date']
        elif pid in lab_certs and 'test_date' in lab_certs[pid]:
            test_date_val = lab_certs[pid]['test_date']

        # We don't actually need to calculate the boolean for the JSON output, 
        # the prompt asks for the facts used in the rule.
        # Wait, the prompt says: "maps each fact name of that rule to one of..."
        # The rules are ea.calibration_current and ea.load_with_margin.
        # The facts for ea.calibration_current are 'calibration date' and 'test date'.

        results[f"ea.calibration_current::{pid}"] = {
            "calibration date": cal_date_val,
            "test date": test_date_val
        }

        # ea.load_with_margin
        # measured load
        measured_load_val = "ABSENT"
        if pid in lab_certs and 'measured_load' in lab_certs[pid]:
            measured_load_val = lab_certs[pid]['measured_load']
        elif pid in test_reps and 'measured_load' in test_reps[pid]:
            measured_load_val = test_reps[pid]['measured_load']

        # specified minimum
        spec_min_val = spec_sheets.get(pid, {}).get('specified_minimum', "ABSENT")

        results[f"ea.load_with_margin::{pid}"] = {
            "measured load": measured_load_val,
            "specified minimum": spec_min_val
        }

    # The prompt asks for the values of the facts. 
    # It doesn't ask for the boolean result of the check, but the facts themselves.
    # However, the rule names are the keys in the output.
    # Let's re-read: "maps each fact name of that rule to one of..."
    # The rule names are ea.calibration_current and ea.load_with_margin.
    # The fact names are 'calibration date', 'test date', 'measured load', 'specified minimum'.

    # One detail: "Report it in kN" for measured load and "Report it in kN" for specified minimum.
    # The values are already decimal strings.

    # Check for CONFLICT
    # The prompt says: "Read a fact from the first listed document that has a value for the entity; use a fallback document only when the first has none."
    # This implies we don't check for conflicts across all documents, but rather follow the priority.
    # BUT, it also says "CONFLICT: the deciding document holds disagreeing values for that entity".
    # This usually means if the primary and fallback disagree.

    # Let's refine the extraction to handle CONFLICT.
    # Re-running logic for each fact:

    final_output = {}

    for pid in pids:
        # ea.calibration_current
        # Fact: calibration date (only from calibration_log)
        # Fact: test date (test_reports, fallback lab_certificates)

        # calibration date
        c_date = cal_log.get(pid, {}).get('calibration_date', "ABSENT")

        # test date
        t_date = "ABSENT"
        if pid in test_reps and 'test_date' in test_reps[pid]:
            t_date = test_reps[pid]['test_date']
        elif pid in lab_certs and 'test_date' in lab_certs[pid]:
            t_date = lab_certs[pid]['test_date']
        # Note: The rule says "if test_reports has no value... use lab_certificates". 
        # This is a fallback mechanism. If both had values, we'd check for conflict.
        # But the rule says "if test_reports has no value", implying we only look at lab_certs if test_reports is empty.
        # However, the "CONFLICT" instruction says "the deciding document holds disagreeing values".
        # Let's check if both exist.
        if pid in test_reps and 'test_date' in test_reps[pid] and pid in lab_certs and 'test_date' in lab_certs[pid]:
            if test_reps[pid]['test_date'][0] != lab_certs[pid]['test_date'][0]:
                t_date = "CONFLICT"

        final_output[f"ea.calibration_current::{pid}"] = {
            "calibration date": c_date,
            "test date": t_date
        }

        # ea.load_with_margin
        # Fact: measured load (lab_certificates, fallback test_reports)
        m_load = "ABSENT"
        if pid in lab_certs and 'measured_load' in lab_certs[pid]:
            m_load = lab_certs[pid]['measured_load']
        elif pid in test_reps and 'measured_load' in test_reps[pid]:
            m_load = test_reps[pid]['measured_load']

        if pid in lab_certs and 'measured_load' in lab_certs[pid] and pid in test_reps and 'measured_load' in test_reps[pid]:
            if lab_certs[pid]['measured_load'][0] != test_reps[pid]['measured_load'][0]:
                m_load = "CONFLICT"

        # Fact: specified minimum (spec_sheets)
        s_min = spec_sheets.get(pid, {}).get('specified_minimum', "ABSENT")

        final_output[f"ea.load_with_margin::{pid}"] = {
            "measured load": m_load,
            "specified minimum": s_min
        }

    print(json.dumps(final_output))

if __name__ == "__main__":
    solve()

