import sys
import os
import json
import datetime

def parse_iso_week(week_str):
    """Parses YYYY-Www-D format to a datetime object."""
    if not week_str or week_str == '~':
        return None
    try:
        # Format: 2026-W01-4
        parts = week_str.split('-')
        year = int(parts[0])
        week = int(parts[1][1:])
        day = int(parts[2])
        # datetime.strptime handles ISO week format %G-W%V-%u
        # %G is ISO year, %V is ISO week, %u is day of week (1-7)
        return datetime.datetime.strptime(f"{year}-W{week:02d}-{day}", "%G-W%V-%u")
    except (ValueError, IndexError):
        return None

def load_tsv(filepath):
    """Loads a TSV file into a dictionary of records."""
    data = {}
    if not os.path.exists(filepath):
        return data
    with open(filepath, 'r') as f:
        lines = f.readlines()

    if not lines:
        return data

    # Find the header row (the one starting with 'attribute')
    header_idx = -1
    for i, line in enumerate(lines):
        if line.startswith('attribute'):
            header_idx = i
            break

    if header_idx == -1:
        return data

    header = lines[header_idx].strip().split('\t')
    # The first column is 'attribute', subsequent are 'rec.NN'
    cols = header[1:]

    # Parse rows
    rows = {}
    for line in lines[header_idx+1:]:
        parts = line.strip().split('\t')
        if not parts:
            continue
        attr = parts[0]
        vals = parts[1:]
        rows[attr] = vals

    # Reorganize into {component_key: {attr: value}}
    # Note: The files are cross-tab, so each column is a record.
    records = {}
    for j in range(len(cols)):
        rec_key = cols[j]
        comp_key = None
        attrs = {}
        for attr, vals in rows.items():
            if j < len(vals):
                val = vals[j]
                if attr == 'component.key':
                    comp_key = val
                attrs[attr] = val

        if comp_key:
            if comp_key not in records:
                records[comp_key] = []
            records[comp_key].append(attrs)

    return records

def main():
    if len(sys.argv) < 2:
        return

    dir_path = sys.argv[1]

    # Load all files
    # calibration_log.tsv
    cal_log = load_tsv(os.path.join(dir_path, 'calibration_log.tsv'))
    # lab_certificates.tsv
    lab_certs = load_tsv(os.path.join(dir_path, 'lab_certificates.tsv'))
    # parts.tsv
    parts = load_tsv(os.path.join(dir_path, 'parts.tsv'))
    # spec_sheets.tsv
    spec_sheets = load_tsv(os.path.join(dir_path, 'spec_sheets.tsv'))
    # test_reports.tsv
    test_reports = load_tsv(os.path.join(dir_path, 'test_reports.tsv'))

    results = {}

    # List of all component keys to check
    all_keys = [f"P-41{i:02d}" for i in range(1, 17)]
    # The prompt asks for specific pairs.
    pairs = []
    for k in all_keys:
        pairs.append(f"ea.calibration_current::{k}")
    for k in all_keys:
        pairs.append(f"ea.load_with_margin::{k}")

    for pair_id in pairs:
        rule, comp_key = pair_id.split('::')
        pair_res = {}

        if rule == 'ea.calibration_current':
            # Fact: calibration date (from calibration_log)
            # Fact: test date (from test_reports, fallback to lab_certificates)

            # 1. Find calibration date for this component
            cal_date = None
            cal_doc = None
            if comp_key in cal_log:
                for entry in cal_log[comp_key]:
                    val = entry.get('rig.cal.wk')
                    if val and val != '~':
                        cal_date = parse_iso_week(val)
                        cal_doc = 'calibration_log.tsv'
                        break

            if cal_date:
                pair_res['calibration date'] = [cal_date.strftime('%Y-%m-%d'), cal_doc]
            else:
                pair_res['calibration date'] = "ABSENT"

            # 2. Find test date
            test_date = None
            test_doc = None

            # Try test_reports
            if comp_key in test_reports:
                for entry in test_reports[comp_key]:
                    val = entry.get('inhouse.break.wk')
                    if val and val != '~':
                        test_date = parse_iso_week(val)
                        test_doc = 'test_reports.tsv'
                        break

            # Fallback to lab_certificates
            if not test_date and comp_key in lab_certs:
                for entry in lab_certs[comp_key]:
                    val = entry.get('lab.break.wk')
                    if val and val != '~':
                        test_date = parse_iso_week(val)
                        test_doc = 'lab_certificates.tsv'
                        break

            if test_date:
                pair_res['test date'] = [test_date.strftime('%Y-%m-%d'), test_doc]
            else:
                pair_res['test date'] = "ABSENT"

        elif rule == 'ea.load_with_margin':
            # Fact: measured load (lab_certificates, fallback to test_reports)
            # Fact: specified minimum (spec_sheets)

            # 1. Measured load
            meas_load = None
            meas_doc = None
            if comp_key in lab_certs:
                for entry in lab_certs[comp_key]:
                    val = entry.get('lab.break.kn')
                    if val and val != '~':
                        meas_load = val
                        meas_doc = 'lab_certificates.tsv'
                        break

            if meas_load is None and comp_key in test_reports:
                for entry in test_reports[comp_key]:
                    val = entry.get('inhouse.break.kn')
                    if val and val != '~':
                        meas_load = val
                        meas_doc = 'test_reports.tsv'
                        break

            if meas_load is not None:
