                        spec_doc = 'spec_sheets.tsv'
                        break

            if spec_min is not None:
                pair_res['specified minimum'] = [spec_min, spec_doc]
            else:
                pair_res['specified minimum'] = "ABSENT"

        results[pair_id] = pair_res

    print(json.dumps(results, indent=2))

if __name__ == "__main__":
