import sys
import os
import json
from datetime import datetime

def parse_date(date_str):
    if not date_str:
        return None
    try:
        return datetime.strptime(date_str.strip(), '%m/%d/%Y')
    except ValueError:
        return None

def parse_decimal(val_str):
    if not val_str:
        return None
    try:
        return float(val_str.strip())
    except ValueError:
        return None

def load_file(directory, filename):
    path = os.path.join(directory, filename)
    if not os.path.exists(path):
        return []
    data = []
    with open(path, 'r') as f:
        lines = f.readlines()
        header = None
        for line in lines:
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            if header is None:
                header = line.split('|')
                continue
            parts = line.split('|')
            if len(parts) == len(header):
                row = dict(zip(header, parts))
                data.append(row)
    return data

def solve():
    if len(sys.argv) < 2:
        return
    dir_path = sys.argv[1]

    cal_log = load_file(dir_path, 'calibration_log.txt')
    lab_certs = load_file(dir_path, 'lab_certificates.txt')
    parts_data = load_file(dir_path, 'parts.txt')
    spec_sheets = load_file(dir_path, 'spec_sheets.txt')
    test_reports = load_file(dir_path, 'test_reports.txt')

    # Indexing
    # cal_log: component_catalog_key -> list of {cal_date, doc_serial}
    cal_map = {}
    for row in cal_log:
        key = row['COMPONENT_CATALOG_KEY']
        cal_date = parse_date(row['LOAD_FRAME_CAL_DAY'])
        if cal_date:
            if key not in cal_map: cal_map[key] = []
            cal_map[key].append({'date': cal_date, 'doc': row['DOCUMENT_SERIAL']})

    # lab_certs: component_catalog_key -> list of {test_date, force_kn, doc_serial}
    lab_map = {}
    for row in lab_certs:
        key = row['COMPONENT_CATALOG_KEY']
        t_date = parse_date(row['ACCREDITED_TRIAL_DAY'])
        force = parse_decimal(row['ACCREDITED_ULTIMATE_FORCE'])
        uom = row['ACCREDITED_ULTIMATE_FORCE_UOM']
        if t_date and force is not None:
            if key not in lab_map: lab_map[key] = []
            val_kn = force if uom == 'KN' else force / 1000.0
            lab_map[key].append({'date': t_date, 'force': val_kn, 'doc': row['DOCUMENT_SERIAL']})

    # test_reports: component_catalog_key -> list of {test_date, force_kn, doc_serial}
    test_map = {}
    for row in test_reports:
        key = row['COMPONENT_CATALOG_KEY']
        t_date = parse_date(row['INTERNAL_TRIAL_DAY'])
        force = parse_decimal(row['INTERNAL_ULTIMATE_FORCE'])
        uom = row['INTERNAL_ULTIMATE_FORCE_UOM']
        if t_date and force is not None:
            if key not in test_map: test_map[key] = []
            val_kn = force if uom == 'KN' else force / 1000.0
            test_map[key].append({'date': t_date, 'force': val_kn, 'doc': row['DOCUMENT_SERIAL']})

    # spec_sheets: component_catalog_key -> {min_force_kn, doc_serial}
    spec_map = {}
    for row in spec_sheets:
        key = row['COMPONENT_CATALOG_KEY']
        min_f = parse_decimal(row['REQUIRED_ULTIMATE_FORCE'])
        uom = row['REQUIRED_ULTIMATE_FORCE_UOM']
        if min_f is not None:
            val_kn = min_f if uom == 'KN' else min_f / 1000.0
            if key not in spec_map: spec_map[key] = []
            spec_map[key].append({'force': val_kn, 'doc': row['DOCUMENT_SERIAL']})

    results = {}

    keys = [f"P-{i:04d}" for i in range(41001, 41017)]

    for key in keys:
        # ea.calibration_current
        pair_id_cal = f"ea.calibration_current::{key}"
        results[pair_id_cal] = {}

        # Find calibration date (from cal_log)
        cal_info = cal_map.get(key, [])
        if not cal_info:
            results[pair_id_cal]['calibration date'] = "ABSENT"
            results[pair_id_cal]['test date'] = "ABSENT"
        else:
            # Rule: first listed document that has a value
            results[pair_id_cal]['calibration date'] = [cal_info[0]['date'].strftime('%Y-%m-%d'), cal_info[0]['doc']]

            # Find test date (lab_certs then test_reports)
            test_date_val = None
            test_date_doc = None

            # Check lab_certs
            l_entries = lab_map.get(key, [])
            if l_entries:
                test_date_val = l_entries[0]['date']
                test_date_doc = l_entries[0]['doc']
            else:
                # Check test_reports
                t_entries = test_map.get(key, [])
                if t_entries:
                    test_date_val = t_entries[0]['date']
                    test_date_doc = t_entries[0]['doc']

            if test_date_val:
                results[pair_id_cal]['test date'] = [test_date_val.strftime('%Y-%m-%d'), test_date_doc]
            else:
                results[pair_id_cal]['test date'] = "ABSENT"

        # ea.load_with_margin
        pair_id_load = f"ea.load_with_margin::{key}"
        results[pair_id_load] = {}

        # Measured load (lab_certs then test_reports)
        measured_val = None
        measured_doc = None
        l_entries = lab_map.get(key, [])
        if l_entries:
            measured_val = l_entries[0]['force']
            measured_doc = l_entries[0]['doc']
        else:
            t_entries = test_map.get(key, [])
            if t_entries:
                measured_val = t_entries[0]['force']
                measured_doc = t_entries[0]['doc']

        if measured_val is not None:
            results[pair_id_load]['measured load'] = [f"{measured_val:.4f}".rstrip('0').rstrip('.'), measured_doc]
        else:
            results[pair_id_load]['measured load'] = "ABSENT"

        # Specified minimum (spec_sheets)
        spec_entries = spec_map.get(key, [])
        if spec_entries:
            results[pair_id_load]['specified minimum'] = [f"{spec_entries[0]['force']:.4f}".rstrip('0').rstrip('.'), spec_entries[0]['doc']]
        else:
            results[pair_id_load]['specified minimum'] = "ABSENT"

    print(json.dumps(results, indent=2))

if __name__ == "__main__":
    solve()
